        echo [luabind DEBUG] $(txt) ;
    }
}

debug-message figuring out which libraries to link to... ;
debug-message os.name is [ os.name ] ;

if [ os.name ] = NT
{
    if ! $(BOOST_ROOT)
    {
        errors.user-error "*** BOOST_ROOT must be set to a Boost installation." ;
    }

