    : <include>. <include>$(BOOST_ROOT)
      $(usage-requirements)
    ;

alias test
  : test//test
  # requirements
  :
  # default-build
  : <link>static <link>shared release debug ;

explicit test ;

rule git-describe ( )
{
    local result = [ SHELL "git describe HEAD 2>&1" : exit-status ] ;

