  : $(headers)
  ;

local stage-locate = [ MATCH "^--stagedir=(.*)" : [ modules.peek : ARGV ] ] ;
stage-locate ?= stage ;

install stage
  : luabind
  : <location>$(stage-locate)
    <install-no-version-symlinks>on
